# Binary rule-based detection
def solve_demo_v2(input_grid):
    h, w = len(input_grid), len(input_grid[0])

    # Check for horizontal separator first (full row of single color)
    for r in range(h):
        row_vals = {input_grid[r][c] for c in range(w)}
        if len(row_vals) == 1:
            return solve_horizontal(input_grid, r)

    # Check for vertical separator (full column of single color)
    for c in range(w):
        col_vals = {input_grid[r][c] for r in range(h)}
        if len(col_vals) == 1:
            return solve_vertical(input_grid, c)

    # No perfect separator, check for approximate
    # For Demo 0, column 10 has mostly 2s with some 4s
    return solve_approx(input_grid)

def solve_horizontal(grid, row_idx):
    """Horizontal split"""
    h, w = len(grid), len(grid[0])
    sep_color = grid[row_idx][0]

    top = [grid[r][:] for r in range(row_idx)]
    bottom = [grid[r][:] for r in range(row_idx + 1, h)]

    result = []
    for r in range(row_idx):
        row = []
        for c in range(w):
            t = top[r][c]
            b = bottom[r][c]
            if t == 4 and b == 4:
                row.append(3)
            else:
                row.append(4)
        result.append(row)
    return result

def solve_vertical(grid, col_idx):
    """Vertical split with separator color in {2,4} → 3, else 4"""
    h, w = len(grid), len(grid[0])
    sep_color = grid[0][col_idx]

    # Override: if it's actually a horizontal problem, return error message
    # Check if sep_color is 2 or if vertical split makes sense
    if h > 10 and sep_color in (2,3,4,5,6,7,8) and sep_color == grid[col_idx][h-1] if h > 1 else False:
        pass

    left_part = col_idx

    left = [[grid[r][c] for c in range(left_part)] for r in range(h)]
    right_part_start = col_idx + 1
    right = [[grid[r][right_part_start + c] for c in range(left_part)] for r in range(h)]

    result = []
    for r in range(h):
        row = []
        for c in range(left_part):
            l = left[r][c]
            r_val = right[r][c]
            # Try rule: both in {sep_color, 4}
            if l in (sep_color, 4) and r_val in (sep_color, 4):
                row.append(3)
            else:
                row.append(4)
        result.append(row)
    return result

def solve_approx(grid):
    """Handle Demo 0 style where separator column has mixed values"""
    h, w = len(grid), len(grid[0])

    # Find column with mostly single value (but not all same)
    for c in range(w):
        col_vals = [grid[r][c] for r in range(h)]
        from collections import Counter
        counts = Counter(col_vals)
        # Check if one simple value is the majority
        max_freq = max(counts.values())
        # Member: the separator is one that has same-majority SIGNAL
        for val, count in counts.items():
            if count > 6:  # More than 6 cells have this value
                # Check if GRID TEMPER fits vertical pattern
                sep_color = val
                left_part = c
                right_part_start = c + 1

                left = [[grid[r][c2] for c2 in range(left_part)] for r in range(h)]
                right = [[grid[r][right_part_start + c2] for c2 in range(left_part)] for r in range(h)]

                result = []
                for r in range(h):
                    row = []
                    for c2 in range(left_part):
                        l = left[r][c2]
                        r_val = right[r][c2]
                        if l in (sep_color, 4) and r_val in (sep_color, 4):
                            row.append(3)
                        else:
                            row.append(4)
                    result.append(row)

                return result

    # Fallback
    return grid

# Test
for i, demo in enumerate(demo_pairs):
    result = solve_demo_v2(demo["input"])
    match = result == demo['output']
    print(f"Demo {i}: sep is vertical with color {sep_color}, match={match}")
    print(f"  Result correct: {match}")

